package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.jsoup.nodes.OuterHtmlTestUtils.createDocument;
import static org.jsoup.nodes.OuterHtmlTestUtils.createElement;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;

public class Element_siblingElements_TriageGen1Test {

    // Tests for siblingElements()

    // Test case 1: Normal usage
    @Test
    public void testSiblingElements_NormalUsage() {
        Element element = createElement("div");
        Elements siblings = element.siblingElements();
        assertNotNull(siblings);
        assertEquals(0, siblings.size());
    }

    // Test case 2: Element with children
    @Test
    public void testSiblingElements_ElementWithChildren() {
        Document document = createDocument("<div><p>Text</p></div>");
        Element element = document.select("div").first();
        Elements siblings = element.siblingElements();
        assertNotNull(siblings);
        assertEquals(1, siblings.size());
    }

    // Test case 3: Element without children
    @Test
    public void testSiblingElements_ElementWithoutChildren() {
        Document document = createDocument("<div><p>Text</p><div></div></div>");
        Element element = document.select("div").get(1);
        Elements siblings = element.siblingElements();
        assertNotNull(siblings);
        assertEquals(0, siblings.size());
    }

    // Test case 4: Element with multiple children
    @Test
    public void testSiblingElements_ElementWithMultipleChildren() {
        Document document = createDocument("<div><p>Text</p><p>More Text</p><div></div></div>");
        Element element = document.select("div").get(1);
        Elements siblings = element.siblingElements();
        assertNotNull(siblings);
        assertEquals(2, siblings.size());
    }

    // Test case 5: Null parent
    @Test
    public void testSiblingElements_NullParent() {
        Element element = createElement("div");
        element.parent(null);
        Elements siblings = element.siblingElements();
        assertNotNull(siblings);
        assertEquals(0, siblings.size());
    }
}
